code_template:
// Use #[cfg] to conditionally compile for ARM vs x86
// Return 64 for ARM (aarch64), 32 for x86_64

fn main() -> Int {
  return 32;  // Assuming x86_64 for this exercise
}

solution:
#[cfg(target_arch = "aarch64")]
fn arch_id() -> Int { return 64; }

#[cfg(target_arch = "x86_64")]
fn arch_id() -> Int { return 32; }

fn main() -> Int {
  return arch_id();
}
